/**
 * Arithmetic in the Rijndael finite field GF(2^8).
 *
 * Every table below is *derived*, never transcribed: the field is generated
 * from the AES reduction polynomial x^8 + x^4 + x^3 + x + 1 (0x11b) so there
 * is no opportunity for a hand-typed constant to be wrong.
 */

/** The AES reduction polynomial, without its x^8 term. */
const REDUCTION_POLY = 0x1b;

/**
 * Multiply `a` by 2 in GF(2^8) (the classic "xtime" operation).
 *
 * @param {number} a byte
 * @returns {number} byte
 */
export function xtime(a) {
  const shifted = (a << 1) & 0xff;
  return a & 0x80 ? shifted ^ REDUCTION_POLY : shifted;
}

/**
 * Multiply two field elements using the russian-peasant algorithm.
 *
 * @param {number} a byte
 * @param {number} b byte
 * @returns {number} byte
 */
export function gmul(a, b) {
  let result = 0;
  let x = a & 0xff;
  let y = b & 0xff;
  while (y) {
    if (y & 1) result ^= x;
    x = xtime(x);
    y >>= 1;
  }
  return result & 0xff;
}

/**
 * Build the discrete log / antilog tables for the field generator 3, which is
 * a primitive element of GF(2^8) under the AES polynomial.
 *
 * @returns {{exp: Uint8Array, log: Uint8Array}}
 */
function buildLogTables() {
  const exp = new Uint8Array(256);
  const log = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i += 1) {
    exp[i] = x;
    log[x] = i;
    x = gmul(x, 3);
  }
  exp[255] = exp[0];
  return { exp, log };
}

const { exp: EXP, log: LOG } = buildLogTables();

/**
 * Multiplicative inverse in GF(2^8); zero is its own (defined) inverse.
 *
 * @param {number} a byte
 * @returns {number} byte
 */
export function ginv(a) {
  if (a === 0) return 0;
  return EXP[255 - LOG[a]];
}

/**
 * Precompute a full 256-entry multiplication table for a fixed multiplier.
 * Used for the MixColumns / InvMixColumns coefficients.
 *
 * @param {number} multiplier byte
 * @returns {Uint8Array}
 */
export function multiplicationTable(multiplier) {
  const table = new Uint8Array(256);
  for (let i = 0; i < 256; i += 1) table[i] = gmul(i, multiplier);
  return table;
}

export { EXP as GF_EXP, LOG as GF_LOG };

