/**
 * The AES substitution boxes, round constants and MixColumns tables.
 *
 * As with `gf.mjs`, every table is computed from its mathematical definition
 * rather than transcribed from FIPS-197.
 */

import { ginv, multiplicationTable, xtime } from './gf.mjs';

/**
 * Rotate a byte left by one bit.
 *
 * @param {number} b byte
 * @returns {number} byte
 */
function rotl8(b) {
  return ((b << 1) | (b >>> 7)) & 0xff;
}

/**
 * The forward S-box: multiplicative inverse in GF(2^8) followed by the
 * Rijndael affine transform  s = b ^ rot1(b) ^ rot2(b) ^ rot3(b) ^ rot4(b) ^ 0x63.
 *
 * @returns {Uint8Array}
 */
function buildSbox() {
  const sbox = new Uint8Array(256);
  for (let i = 0; i < 256; i += 1) {
    const b = ginv(i);
    let s = b;
    let r = b;
    for (let k = 0; k < 4; k += 1) {
      r = rotl8(r);
      s ^= r;
    }
    sbox[i] = (s ^ 0x63) & 0xff;
  }
  return sbox;
}

/**
 * Invert a bijective byte table.
 *
 * @param {Uint8Array} table
 * @returns {Uint8Array}
 */
function invertTable(table) {
  const inverse = new Uint8Array(256);
  for (let i = 0; i < 256; i += 1) inverse[table[i]] = i;
  return inverse;
}

/**
 * Round constants: RCON[i] = x^(i-1) in GF(2^8). Index 0 is unused padding so
 * the table can be indexed directly by the key-schedule round number.
 *
 * 15 entries covers AES-128 (10 rounds) through AES-256 (14 rounds); AES-128
 * needs the highest index, i / Nk = 10.
 *
 * @returns {Uint8Array}
 */
function buildRcon() {
  const rcon = new Uint8Array(16);
  let value = 1;
  for (let i = 1; i < rcon.length; i += 1) {
    rcon[i] = value;
    value = xtime(value);
  }
  return rcon;
}

export const SBOX = buildSbox();
export const INV_SBOX = invertTable(SBOX);
export const RCON = buildRcon();

/** MixColumns coefficients. */
export const MUL2 = multiplicationTable(2);
export const MUL3 = multiplicationTable(3);

/** InvMixColumns coefficients. */
export const MUL9 = multiplicationTable(9);
export const MUL11 = multiplicationTable(11);
export const MUL13 = multiplicationTable(13);
export const MUL14 = multiplicationTable(14);

