/**
 * Rijndael key expansion for 128-, 192- and 256-bit keys.
 */

import { RCON, SBOX } from './tables.mjs';

/** AES operates on 4-byte words and a 16-byte block. */
export const WORD_SIZE = 4;
export const BLOCK_SIZE = 16;

/** Key sizes accepted by AES, in bytes. */
export const VALID_KEY_SIZES = [16, 24, 32];

/**
 * Substitute all four bytes of a word through the S-box.
 *
 * @param {number} word unsigned 32-bit
 * @returns {number} unsigned 32-bit
 */
function subWord(word) {
  return (
    ((SBOX[(word >>> 24) & 0xff] << 24) |
      (SBOX[(word >>> 16) & 0xff] << 16) |
      (SBOX[(word >>> 8) & 0xff] << 8) |
      SBOX[word & 0xff]) >>>
    0
  );
}

/**
 * Rotate a word one byte to the left.
 *
 * @param {number} word unsigned 32-bit
 * @returns {number} unsigned 32-bit
 */
function rotWord(word) {
  return (((word << 8) | (word >>> 24)) & 0xffffffff) >>> 0;
}

/**
 * Number of cipher rounds for a given key length in bytes.
 *
 * @param {number} keyLength
 * @returns {number}
 */
export function roundCount(keyLength) {
  return keyLength / WORD_SIZE + 6;
}

/**
 * Expand a cipher key into the round-key word schedule.
 *
 * @param {Uint8Array} key 16, 24 or 32 bytes
 * @returns {Uint32Array} 4 * (rounds + 1) words, big-endian per word
 */
export function expandKey(key) {
  const nk = key.length / WORD_SIZE;
  const rounds = roundCount(key.length);
  const total = WORD_SIZE * (rounds + 1);
  const schedule = new Uint32Array(total);

  for (let i = 0; i < nk; i += 1) {
    const o = i * WORD_SIZE;
    schedule[i] =
      ((key[o] << 24) | (key[o + 1] << 16) | (key[o + 2] << 8) | key[o + 3]) >>> 0;
  }

  for (let i = nk; i < total; i += 1) {
    let temp = schedule[i - 1];
    if (i % nk === 0) {
      temp = (subWord(rotWord(temp)) ^ (RCON[i / nk] << 24)) >>> 0;
    } else if (nk > 6 && i % nk === 4) {
      temp = subWord(temp);
    }
    schedule[i] = (schedule[i - nk] ^ temp) >>> 0;
  }

  return schedule;
}

