/**
 * Minimal stand-ins for the CPython exception types this program can raise.
 *
 * Keeping them as real `Error` subclasses lets the entry script dispatch on
 * `instanceof` exactly the way the Python interpreter dispatches on the
 * exception class when it formats a traceback.
 */

/**
 * Base class carrying the dotted name CPython would print before the message.
 */
export class PythonError extends Error {
  /**
   * @param {string} pythonType name as it appears in a traceback
   * @param {string} message the exception's `str()`
   */
  constructor(pythonType, message) {
    super(message);
    this.pythonType = pythonType;
    /** Frames appended below the caller's frames, innermost last. */
    this.pythonFrames = [];
  }
}

/** `ValueError` */
export class ValueError extends PythonError {
  /** @param {string} message */
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * `UnicodeEncodeError`.
 *
 * CPython renders it as
 *   'utf-8' codec can't encode character '\udcff' in position 13: <reason>
 * for a single offending code point and
 *   'utf-8' codec can't encode characters in position 0-1: <reason>
 * for a run of two or more.
 */
export class UnicodeEncodeError extends PythonError {
  /**
   * @param {string} encoding e.g. 'utf-8'
   * @param {string} object the string being encoded
   * @param {number} start first offending code-point index
   * @param {number} end one past the last offending code-point index
   * @param {string} reason human-readable cause
   */
  constructor(encoding, object, start, end, reason) {
    super('UnicodeEncodeError', '');
    this.encoding = encoding;
    this.object = object;
    this.start = start;
    this.end = end;
    this.reason = reason;
    this.message = formatUnicodeEncodeError(this);
  }
}

/**
 * Escape a single code point the way CPython's `repr()` of a `str` would, for
 * embedding in a UnicodeEncodeError message.
 *
 * @param {number} codePoint
 * @returns {string}
 */
function reprCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * Reproduce CPython's `UnicodeEncodeError.__str__`.
 *
 * @param {UnicodeEncodeError} error
 * @returns {string}
 */
function formatUnicodeEncodeError(error) {
  const codePoints = Array.from(error.object);
  if (error.end === error.start + 1) {
    const one = codePoints[error.start];
    const point = one === undefined ? 0 : one.codePointAt(0);
    return (
      `'${error.encoding}' codec can't encode character '${reprCodePoint(point)}' ` +
      `in position ${error.start}: ${error.reason}`
    );
  }
  return (
    `'${error.encoding}' codec can't encode characters ` +
    `in position ${error.start}-${error.end - 1}: ${error.reason}`
  );
}

