/**
 * The AES block cipher itself: one 16-byte block in, one 16-byte block out.
 *
 * The state is held as a flat 16-byte array in AES column-major order, i.e.
 * `state[4 * column + row]`, which is also the order bytes arrive in.
 */

import { ValueError } from '../python/exceptions.mjs';
import { expandKey, roundCount, BLOCK_SIZE, VALID_KEY_SIZES } from './keyExpansion.mjs';
import {
  INV_SBOX,
  MUL11,
  MUL13,
  MUL14,
  MUL2,
  MUL3,
  MUL9,
  SBOX,
} from './tables.mjs';

/**
 * XOR one round key into the state.
 *
 * @param {Uint8Array} state
 * @param {Uint32Array} schedule
 * @param {number} round
 */
function addRoundKey(state, schedule, round) {
  for (let column = 0; column < 4; column += 1) {
    const word = schedule[round * 4 + column];
    const o = column * 4;
    state[o] ^= (word >>> 24) & 0xff;
    state[o + 1] ^= (word >>> 16) & 0xff;
    state[o + 2] ^= (word >>> 8) & 0xff;
    state[o + 3] ^= word & 0xff;
  }
}

/**
 * Apply a byte substitution table to the whole state.
 *
 * @param {Uint8Array} state
 * @param {Uint8Array} table
 */
function substituteBytes(state, table) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] = table[state[i]];
}

/**
 * ShiftRows: row r rotates left by r columns.
 *
 * @param {Uint8Array} state
 */
function shiftRows(state) {
  const source = state.slice();
  for (let row = 1; row < 4; row += 1) {
    for (let column = 0; column < 4; column += 1) {
      state[column * 4 + row] = source[(((column + row) % 4) * 4) + row];
    }
  }
}

/**
 * InvShiftRows: row r rotates right by r columns.
 *
 * @param {Uint8Array} state
 */
function invShiftRows(state) {
  const source = state.slice();
  for (let row = 1; row < 4; row += 1) {
    for (let column = 0; column < 4; column += 1) {
      state[column * 4 + row] = source[(((column - row + 4) % 4) * 4) + row];
    }
  }
}

/**
 * MixColumns: multiply each column by the fixed polynomial {03}x^3 + {01}x^2 +
 * {01}x + {02}.
 *
 * @param {Uint8Array} state
 */
function mixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const o = column * 4;
    const a0 = state[o];
    const a1 = state[o + 1];
    const a2 = state[o + 2];
    const a3 = state[o + 3];
    state[o] = MUL2[a0] ^ MUL3[a1] ^ a2 ^ a3;
    state[o + 1] = a0 ^ MUL2[a1] ^ MUL3[a2] ^ a3;
    state[o + 2] = a0 ^ a1 ^ MUL2[a2] ^ MUL3[a3];
    state[o + 3] = MUL3[a0] ^ a1 ^ a2 ^ MUL2[a3];
  }
}

/**
 * InvMixColumns: multiply each column by the inverse polynomial
 * {0b}x^3 + {0d}x^2 + {09}x + {0e}.
 *
 * @param {Uint8Array} state
 */
function invMixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const o = column * 4;
    const a0 = state[o];
    const a1 = state[o + 1];
    const a2 = state[o + 2];
    const a3 = state[o + 3];
    state[o] = MUL14[a0] ^ MUL11[a1] ^ MUL13[a2] ^ MUL9[a3];
    state[o + 1] = MUL9[a0] ^ MUL14[a1] ^ MUL11[a2] ^ MUL13[a3];
    state[o + 2] = MUL13[a0] ^ MUL9[a1] ^ MUL14[a2] ^ MUL11[a3];
    state[o + 3] = MUL11[a0] ^ MUL13[a1] ^ MUL9[a2] ^ MUL14[a3];
  }
}

/**
