      substituteBytes(state, SBOX);
      shiftRows(state);
      mixColumns(state);
      addRoundKey(state, this.schedule, round);
    }
    substituteBytes(state, SBOX);
    shiftRows(state);
    addRoundKey(state, this.schedule, this.rounds);
    return state;
  }

  /**
   * Decrypt exactly one block.
   *
   * @param {Uint8Array} block 16 bytes
   * @returns {Uint8Array} 16 bytes
