/**
 * Frame bookkeeping shared by the library and the entry script.
 *
 * The PyInstaller bundle the reference program runs from does not ship the
 * `pyaes` sources, so frames from inside the library print as a bare
 * `File "..." , line N, in name` with no echoed source line. Frames from the
 * user script do echo their source, plus the 3.11+ caret line marking the
 * failing sub-expression.
 */

/**
 * Describe one traceback frame.
 *
 * @param {string} file path as CPython would print it
 * @param {number} line 1-based line number
 * @param {string} name enclosing function name, or '<module>'
 * @param {{source?: string, caretStart?: number, caretLength?: number}} [detail]
 * @returns {{file: string, line: number, name: string, source?: string,
 *            caretStart?: number, caretLength?: number}}
 */
export function frame(file, line, name, detail = {}) {
  return { file, line, name, ...detail };
}

/**
 * Push a frame onto an in-flight exception as it propagates outwards.
 *
 * Traceback frames print outermost first, so an outer frame goes to the front.
 *
 * @template {Error & {pythonFrames?: object[]}} E
 * @param {E} error
 * @param {object} outerFrame
 * @returns {E} the same error, for `throw addOuterFrame(...)`
 */
export function addOuterFrame(error, outerFrame) {
  if (!Array.isArray(error.pythonFrames)) error.pythonFrames = [];
  error.pythonFrames.unshift(outerFrame);
  return error;
}

