/**
 * pyaes modes of operation. Only ECB is needed here, and only its
 * single-block behaviour.
 */

import { ValueError } from '../python/exceptions.mjs';
import { addOuterFrame, frame } from '../python/frames.mjs';
import { AES } from './blockCipher.mjs';
import { BLOCK_SIZE } from './keyExpansion.mjs';

/** Line numbers pyaes reports in its tracebacks, as observed from the bundle. */
const AES_INIT_LINE = 134;
const ECB_INIT_LINE = 304;
const ECB_ENCRYPT_LINE = 342;
const ECB_DECRYPT_LINE = 349;
const SOURCE = 'pyaes/aes.py';

/**
 * AES applied one block at a time with no chaining — Electronic Codebook.
 *
 * `encrypt` and `decrypt` each require exactly one 16-byte block; unlike the
 * buffered `Encrypter`/`Decrypter` wrappers, this class does no padding.
 */
export class AESModeOfOperationECB {
  /**
   * @param {Uint8Array} key 16, 24 or 32 bytes
   */
  constructor(key) {
    try {
      this._aes = new AES(key);
    } catch (error) {
      if (error instanceof ValueError) {
        addOuterFrame(error, frame(SOURCE, AES_INIT_LINE, '__init__'));
        throw addOuterFrame(error, frame(SOURCE, ECB_INIT_LINE, '__init__'));
      }
      throw error;
    }
  }

  /** @returns {string} */
  get name() {
    return 'Electronic Codebook (ECB)';
  }

  /**
   * Encrypt one block.
   *
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} 16 bytes of ciphertext
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw addOuterFrame(
        new ValueError('plaintext block must be 16 bytes'),
        frame(SOURCE, ECB_ENCRYPT_LINE, 'encrypt'),
      );
    }
    return this._aes.encrypt(plaintext);
  }

  /**
   * Decrypt one block.
   *
   * @param {Uint8Array} ciphertext exactly 16 bytes
   * @returns {Uint8Array} 16 bytes of plaintext
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw addOuterFrame(
        new ValueError('ciphertext block must be 16 bytes'),
        frame(SOURCE, ECB_DECRYPT_LINE, 'decrypt'),
      );
    }
    return this._aes.decrypt(ciphertext);
  }
}

