/**
 * CPython's `repr()` for `bytes` objects.
 *
 * `print(b'...')` goes through `str(bytes)`, which is `repr`, so this function
 * is what produces the program's entire stdout.
 */

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SPACE = 0x20;
const DELETE = 0x7f;

/**
 * Pick the delimiter CPython would use: a single quote unless the payload
 * contains a single quote but no double quote, in which case double quotes
 * avoid an escape.
 *
 * @param {Uint8Array} data
 * @returns {number} the quote byte
 */
function chooseQuote(data) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < data.length; i += 1) {
    if (data[i] === SINGLE_QUOTE) hasSingle = true;
    else if (data[i] === DOUBLE_QUOTE) hasDouble = true;
  }
  return hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
}

/**
 * Format a byte string exactly as `repr()` would, e.g.
 * `b'\xb7\x9c8@/\xabc\x8c\xf0@\xad\xec\xd3\xce\x81\t'`.
 *
 * @param {Uint8Array} data
 * @returns {string} ASCII-only representation
 */
export function reprBytes(data) {
  const quote = chooseQuote(data);
  const quoteChar = String.fromCharCode(quote);
  let out = `b${quoteChar}`;

  for (let i = 0; i < data.length; i += 1) {
    const byte = data[i];
    if (byte === quote || byte === BACKSLASH) {
      out += `\\${String.fromCharCode(byte)}`;
    } else if (byte === TAB) {
      out += '\\t';
    } else if (byte === NEWLINE) {
      out += '\\n';
    } else if (byte === CARRIAGE_RETURN) {
      out += '\\r';
    } else if (byte < SPACE || byte >= DELETE) {
      out += `\\x${byte.toString(16).padStart(2, '0')}`;
    } else {
      out += String.fromCharCode(byte);
    }
  }

  return out + quoteChar;
}

