/**
 * The two text codecs this program depends on.
 *
 * A Python `str` is modelled as a JavaScript string that may contain lone
 * surrogates in U+DC80..U+DCFF — exactly what `errors='surrogateescape'`
 * produces for bytes that are not valid UTF-8. JavaScript strings tolerate
 * lone surrogates, so the model is faithful, including the fact that encoding
 * such a string back to UTF-8 with strict errors fails.
 */

import { UnicodeEncodeError } from './exceptions.mjs';

const SURROGATE_LOW = 0xd800;
const SURROGATE_HIGH = 0xdfff;
const SURROGATE_ESCAPE_BASE = 0xdc00;

/**
 * How many continuation bytes a lead byte announces, and the legal range of
 * the first continuation. Returns null for bytes that cannot start a sequence.
 *
 * @param {number} lead
 * @returns {{length: number, min: number, max: number} | null}
 */
function leadByteInfo(lead) {
  if (lead < 0x80) return { length: 1, min: 0, max: 0 };
  if (lead < 0xc2) return null; // continuation byte, or overlong C0/C1
  if (lead < 0xe0) return { length: 2, min: 0x80, max: 0xbf };
  if (lead === 0xe0) return { length: 3, min: 0xa0, max: 0xbf }; // no overlongs
  if (lead === 0xed) return { length: 3, min: 0x80, max: 0x9f }; // no surrogates
  if (lead < 0xf0) return { length: 3, min: 0x80, max: 0xbf };
  if (lead === 0xf0) return { length: 4, min: 0x90, max: 0xbf }; // no overlongs
  if (lead === 0xf4) return { length: 4, min: 0x80, max: 0x8f }; // <= U+10FFFF
  if (lead < 0xf4) return { length: 4, min: 0x80, max: 0xbf };
  return null; // 0xf5..0xff are always invalid
}

/**
 * Decode bytes as UTF-8, mapping each undecodable byte to U+DC00 + byte the way
 * CPython's `surrogateescape` handler does. This is how the interpreter turns
 * `argv` into `str` objects.
 *
 * @param {Uint8Array} bytes
 * @returns {string} a Python-`str`-shaped JavaScript string
 */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;

  /**
   * Escape `count` bytes starting at `from` and advance past them.
   *
   * @param {number} from
   * @param {number} count
   */
  const escapeRun = (from, count) => {
    for (let k = 0; k < count; k += 1) {
      out += String.fromCharCode(SURROGATE_ESCAPE_BASE + bytes[from + k]);
    }
  };

  while (i < bytes.length) {
    const lead = bytes[i];
    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    const info = leadByteInfo(lead);
    if (info === null) {
      escapeRun(i, 1);
      i += 1;
      continue;
    }

    // Count how much of the announced sequence is actually well formed.
    let consumed = 1;
    let valid = true;
    for (let k = 1; k < info.length; k += 1) {
      const byte = bytes[i + k];
      const min = k === 1 ? info.min : 0x80;
      const max = k === 1 ? info.max : 0xbf;
      if (byte === undefined || byte < min || byte > max) {
        valid = false;
        break;
      }
      consumed += 1;
    }

    if (!valid) {
      // CPython escapes the well-formed prefix and resumes at the offender.
      escapeRun(i, consumed);
      i += consumed;
      continue;
    }

    let codePoint = lead & (0xff >> (info.length + 1));
    for (let k = 1; k < info.length; k += 1) {
      codePoint = (codePoint << 6) | (bytes[i + k] & 0x3f);
    }
    out += String.fromCodePoint(codePoint);
    i += info.length;
  }

  return out;
}

/**
 * Encode a Python `str` as UTF-8 with `errors='strict'`, raising
 * `UnicodeEncodeError` for lone surrogates — including the surrogate-escaped
 * bytes produced by {@link decodeSurrogateEscape}.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function encodeUtf8Strict(text) {
  const codePoints = Array.from(text);
  for (let i = 0; i < codePoints.length; i += 1) {
    const point = codePoints[i].codePointAt(0);
    if (point >= SURROGATE_LOW && point <= SURROGATE_HIGH) {
