/**
 * Recovering the *bytes* of `argv`.
 *
 * Node decodes `process.argv` as lossy UTF-8, replacing malformed bytes with
 * U+FFFD, which destroys the distinction CPython preserves via
 * `surrogateescape`. On Linux the original bytes are still available through
 * `/proc/self/cmdline`, so read them from there and fall back to the decoded
 * strings anywhere that is unavailable.
 */

import { readFileSync } from 'node:fs';
import { decodeSurrogateEscape } from './codecs.mjs';

const CMDLINE = '/proc/self/cmdline';

/**
 * Split a NUL-delimited blob into its records.
 *
 * @param {Buffer} blob
 * @returns {Buffer[]}
 */
function splitNulDelimited(blob) {
  const parts = [];
  let start = 0;
  for (let i = 0; i < blob.length; i += 1) {
    if (blob[i] === 0) {
      parts.push(blob.subarray(start, i));
      start = i + 1;
    }
  }
  if (start < blob.length) parts.push(blob.subarray(start));
  return parts;
}

/**
 * Whether a buffer is well-formed UTF-8.
 *
 * @param {Buffer} buffer
 * @returns {boolean}
 */
function isValidUtf8(buffer) {
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(buffer);
    return true;
  } catch {
    return false;
  }
}

/**
 * The raw bytes of the user-supplied arguments, i.e. everything after the
 * interpreter and the script path.
 *
 * @returns {Uint8Array[]}
 */
export function rawArgumentBytes() {
  const wanted = process.argv.length - 2;
  const fallback = () =>
    process.argv.slice(2).map((argument) => new Uint8Array(Buffer.from(argument, 'utf8')));

  if (wanted <= 0) return [];

  try {
    const parts = splitNulDelimited(readFileSync(CMDLINE));
    if (parts.length < wanted) return fallback();
    const tail = parts.slice(parts.length - wanted);

    // Guard against an unexpected cmdline layout: any argument that survived
    // Node's decoding intact must match what we picked up here.
    for (let i = 0; i < wanted; i += 1) {
      if (isValidUtf8(tail[i]) && tail[i].toString('utf8') !== process.argv[i + 2]) {
        return fallback();
      }
    }
    return tail.map((part) => new Uint8Array(part));
  } catch {
    return fallback();
  }
}

/**
 * `sys.argv[1:]` as CPython would see it: strings that may contain
 * surrogate-escaped bytes.
 *
 * @returns {string[]}
 */
export function pythonArgv() {
  return rawArgumentBytes().map(decodeSurrogateEscape);
}

/**
 * `os.path.basename(sys.argv[0])`, which argparse uses as the default `prog`.
 *
 * @returns {string}
 */
export function programName() {
  const scriptPath = process.argv[1] ?? '';
  const separator = scriptPath.lastIndexOf('/');
  return separator === -1 ? scriptPath : scriptPath.slice(separator + 1);
}

