/**
 * The slice of `sys` this program touches.
 *
 * Writes go out as raw bytes so nothing re-encodes the text on its way to the
 * pipe. On Linux, Node's writes to files, TTYs and pipes are all synchronous,
 * so output cannot be lost to a subsequent `process.exit`.
 */

/**
 * `sys.stdout.write`
 *
 * @param {string} text
 */
export function writeStdout(text) {
  process.stdout.write(Buffer.from(text, 'utf8'));
}

/**
 * `sys.stderr.write`
 *
 * @param {string} text
 */
export function writeStderr(text) {
  process.stderr.write(Buffer.from(text, 'utf8'));
}

/**
 * `print(...)` for a single already-stringified argument.
 *
 * @param {string} text
 */
export function print(text) {
  writeStdout(`${text}\n`);
}

/**
 * `sys.exit(status)`
 *
 * @param {number} status
 * @returns {never}
 */
export function exit(status) {
  process.exit(status);
}

/**
 * The width argparse formats help against.
 *
 * `shutil.get_terminal_size()` prefers `$COLUMNS`, then the terminal, then
 * falls back to 80 columns — which is what happens whenever stdout is a pipe.
 *
 * @returns {number} total columns
 */
export function terminalColumns() {
  const fromEnvironment = Number.parseInt(process.env.COLUMNS ?? '', 10);
  if (Number.isInteger(fromEnvironment) && fromEnvironment > 0) return fromEnvironment;
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

