/**
 * `textwrap`-compatible greedy line wrapping, as used by argparse's
 * `HelpFormatter._split_lines`.
 */

/**
 * Collapse every run of whitespace to a single space and trim, matching
 * `HelpFormatter._whitespace_matcher.sub(' ', text).strip()`.
 *
 * @param {string} text
 * @returns {string}
 */
export function collapseWhitespace(text) {
  return text.replace(/[\t\n\x0b\f\r ]+/g, ' ').trim();
}

/**
 * Greedy wrap on spaces, breaking words that cannot fit on a line by
 * themselves (textwrap's `break_long_words=True` default).
 *
 * @param {string} text already whitespace-collapsed
 * @param {number} width maximum line length, at least 1
 * @returns {string[]}
 */
export function wrapText(text, width) {
  const limit = Math.max(1, width);
  const lines = [];
  let line = '';

  for (const word of text.split(' ')) {
    if (word === '') continue;
    if (line === '') {
      line = word;
    } else if (line.length + 1 + word.length <= limit) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
    while (line.length > limit) {
      lines.push(line.slice(0, limit));
      line = line.slice(limit);
    }
  }

  if (line !== '') lines.push(line);
  return lines;
}

