/**
 * A faithful subset of CPython 3.12's `argparse`.
 *
 * Only what this program's parser can reach is modelled — optionals with
 * `nargs=None` plus the automatic `-h/--help` — but within that subset the
 * observable behaviour is reproduced precisely: prefix abbreviation, `--opt=value`,
 * the `--` terminator, the negative-number heuristic, the space heuristic,
 * short-option tails such as `-hx`, ambiguity reporting, the ordering of the
 * "required" check before the "unrecognized" check, and exit statuses.
 */

import { HelpFormatter } from './argparseFormatter.mjs';
import { exit, terminalColumns, writeStderr, writeStdout } from './sys.mjs';

const PREFIX_CHARS = '-';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Exit status argparse uses for command-line errors. */
const USAGE_ERROR_STATUS = 2;

/**
 * One command-line action.
 */
class Action {
  /**
   * @param {string[]} optionStrings e.g. ['-h', '--help']
   * @param {{kind?: 'store' | 'help', dest?: string, metavar?: string,
   *          required?: boolean, help?: string}} options
   */
  constructor(optionStrings, options = {}) {
    this.optionStrings = optionStrings;
    this.kind = options.kind ?? 'store';
    this.required = options.required ?? false;
    this.help = options.help ?? '';
    this.nargs = this.kind === 'help' ? 0 : null;
    this.dest = options.dest ?? Action.defaultDest(optionStrings);
    this.metavar = options.metavar ?? this.dest.toUpperCase();
  }

  /**
   * argparse derives `dest` from the first long option string.
   *
   * @param {string[]} optionStrings
   * @returns {string}
   */
  static defaultDest(optionStrings) {
    const long = optionStrings.find((option) => option.startsWith('--')) ?? optionStrings[0];
    return long.replace(/^-+/, '').replace(/-/g, '_');
  }

  /** `_get_action_name`: how the action is named in error messages. */
  get displayName() {
    return this.optionStrings.join('/');
  }
}

export class ArgumentParser {
  /**
   * @param {{prog: string}} options
   */
  constructor({ prog }) {
    this.prog = prog;
    /** @type {Action[]} */
    this.actions = [];
    /** @type {Map<string, Action>} */
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      kind: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * Register an option.
   *
   * @param {string[]} optionStrings
   * @param {object} [options] see {@link Action}
   * @returns {Action}
   */
  addArgument(optionStrings, options = {}) {
    const action = new Action(optionStrings, options);
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /** @returns {HelpFormatter} */
  formatter() {
    return new HelpFormatter(this.prog, terminalColumns());
  }

  /** @returns {string} */
  formatUsage() {
    return this.formatter().formatUsage(this.actions);
  }

  /** @returns {string} */
  formatHelp() {
    return this.formatter().formatHelp(this.actions);
  }

  /**
   * `parser.error`: usage plus a diagnostic on stderr, then exit status 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    return exit(USAGE_ERROR_STATUS);
  }

  /**
   * Classify one token: `null` means "positional", otherwise a tuple of the
   * matched action (or `null` for an unknown option), the option string, and
   * any value glued on with `=`.
   *
   * @param {string} token
   * @returns {{action: Action | null, optionString: string, explicitArg: string | null} | null}
   */
  parseOptional(token) {
    if (token === '') return null;
    if (!PREFIX_CHARS.includes(token[0])) return null;

    const exact = this.optionStringActions.get(token);
    if (exact !== undefined) return { action: exact, optionString: token, explicitArg: null };

    if (token.length === 1) return null; // a bare '-' is a positional

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const head = token.slice(0, equals);
      const action = this.optionStringActions.get(head);
      if (action !== undefined) {
        return { action, optionString: head, explicitArg: token.slice(equals + 1) };
      }
    }

    const candidates = this.getOptionTuples(token);
    if (candidates.length > 1) {
      const matches = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (candidates.length === 1) return candidates[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // meant to be a negative number
    if (token.includes(' ')) return null; // meant to be a positional

    return { action: null, optionString: token, explicitArg: null };
  }

  /**
   * All options an abbreviation could refer to (`_get_option_tuples`).
   *
   * @param {string} token
   * @returns {{action: Action, optionString: string, explicitArg: string | null}[]}
   */
  getOptionTuples(token) {
    const result = [];
    const doubleDash = PREFIX_CHARS.includes(token[0]) && PREFIX_CHARS.includes(token[1]);

    if (doubleDash) {
      const equals = token.indexOf('=');
      const optionPrefix = equals === -1 ? token : token.slice(0, equals);
      const explicitArg = equals === -1 ? null : token.slice(equals + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
      return result;
    }

    // Single dash: either an exact short option with its value glued on, or an
    // abbreviation of a longer single-dash option.
    const shortOptionPrefix = token.slice(0, 2);
    const shortExplicitArg = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(token)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

