   * `_match_argument` for the nargs values this parser uses. Optionals never
   * consume `--`, so the pattern for `nargs=None` is simply a single 'A'.
   *
   * @param {Action} action
   * @param {string} patterns remaining token-class pattern
   * @returns {number} how many tokens the action consumes
   */
  matchArgument(action, patterns) {
    if (action.nargs === 0) return 0;
    if (patterns.startsWith('A')) return 1;
    return this.error(`argument ${action.displayName}: expected one argument`);
  }

  /**
   * Parse, tolerating unknown tokens by collecting them.
   *
   * @param {string[]} argv
   * @returns {[Record<string, string | null>, string[]]}
   */
  parseKnownArgs(argv) {
    /** @type {Record<string, string | null>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === 'store') namespace[action.dest] = null;
    }

    // Classify every token up front; the first '--' makes all that follow
    // positional, and is itself neither option nor value.
    const patterns = [];
    /** @type {Map<number, {action: Action | null, optionString: string, explicitArg: string | null}>} */
    const optionTuples = new Map();
    let terminated = false;
    for (let i = 0; i < argv.length; i += 1) {
      if (!terminated && argv[i] === '--') {
        patterns.push('-');
        terminated = true;
        continue;
      }
      if (terminated) {
        patterns.push('A');
        continue;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        patterns.push('A');
      } else {
        optionTuples.set(i, tuple);
        patterns.push('O');
      }
    }
    const patternString = patterns.join('');

    /** @type {string[]} */
    const extras = [];
    /** @type {Set<Action>} */
    const seen = new Set();

    /**
     * Apply an action, which for `--help` never returns.
     *
     * @param {Action} action
     * @param {string[]} values
     */
    const takeAction = (action, values) => {
      seen.add(action);
      if (action.kind === 'help') {
        writeStdout(this.formatHelp());
        exit(0);
      }
      namespace[action.dest] = values[0];
    };

    let index = 0;
    while (index < argv.length) {
      if (patternString[index] !== 'O') {
        // No positionals are defined, so every positional token is a leftover.
        extras.push(argv[index]);
        index += 1;
        continue;
      }
      index = this.consumeOptional(index, argv, patternString, optionTuples, extras, takeAction);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.displayName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * Consume one option and its value, returning the next index to look at.
   *
   * @param {number} startIndex
   * @param {string[]} argv
   * @param {string} patternString
   * @param {Map<number, object>} optionTuples
   * @param {string[]} extras
   * @param {(action: Action, values: string[]) => void} takeAction
   * @returns {number}
   */
  consumeOptional(startIndex, argv, patternString, optionTuples, extras, takeAction) {
    let { action, optionString, explicitArg } = optionTuples.get(startIndex);
    /** @type {[Action, string[]][]} */
    const pending = [];
    let stop = startIndex + 1;

    for (;;) {
      if (action === null) {
        // An option nobody declared: hand the token back as a leftover.
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = this.matchArgument(action, 'A');
        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          // A short flag with a tail, e.g. '-hx': run the flag, then try to
          // read the tail as another short option.
          pending.push([action, []]);
          const prefixChar = optionString[0];
          optionString = prefixChar + explicitArg[0];
          const remainder = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
          const next = this.optionStringActions.get(optionString);
          if (next !== undefined) {
            action = next;
            explicitArg = remainder;
            continue;
          }
          extras.push(prefixChar + explicitArg);
          stop = startIndex + 1;
          break;
        }
        if (argCount === 1) {
          pending.push([action, [explicitArg]]);
          stop = startIndex + 1;
          break;
        }
        this.error(`argument ${action.displayName}: ignored explicit argument '${explicitArg}'`);
      }

      const valueStart = startIndex + 1;
      const argCount = this.matchArgument(action, patternString.slice(valueStart));
      stop = valueStart + argCount;
      pending.push([action, argv.slice(valueStart, stop)]);
      break;
    }

    for (const [pendingAction, values] of pending) takeAction(pendingAction, values);
    return stop;
  }

  /**
   * Parse, rejecting anything left over.
   *
   * @param {string[]} argv
   * @returns {Record<string, string | null>}
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

