/**
 * Rendering an unhandled exception the way CPython 3.12 does, including the
 * caret line that marks the failing sub-expression, plus the trailing notice
 * the PyInstaller bootloader prints for the frozen script.
 */

import { writeStderr } from './sys.mjs';

/** Exit status the interpreter uses for an unhandled exception. */
const UNHANDLED_EXCEPTION_STATUS = 1;

/**
 * Render a traceback for an exception carrying `pythonType`, `message` and
 * `pythonFrames`.
 *
 * @param {{pythonType: string, message: string, pythonFrames: object[]}} error
 * @returns {string}
 */
export function formatTraceback(error) {
  let out = 'Traceback (most recent call last):\n';

  for (const frame of error.pythonFrames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
    if (frame.source === undefined) continue;

    out += `    ${frame.source}\n`;
    const { caretStart, caretLength } = frame;
    if (caretStart === undefined || caretLength === undefined) continue;
    // CPython omits the carets when they would underline the whole statement.
    if (caretStart === 0 && caretLength === frame.source.length) continue;
    out += `    ${' '.repeat(caretStart)}${'^'.repeat(caretLength)}\n`;
  }

  return `${out}${error.pythonType}: ${error.message}\n`;
}

/**
 * Print the traceback and flag the failing exit status.
 *
 * The status is set rather than forced through `process.exit` so nothing can
 * cut the diagnostic short.
 *
 * @param {{pythonType: string, message: string, pythonFrames: object[]}} error
 * @param {string} frozenScriptName name the bootloader reports
 */
export function reportUnhandledException(error, frozenScriptName) {
  writeStderr(formatTraceback(error));
  writeStderr(
    `[PYI-${process.pid}:ERROR] Failed to execute script ` +
      `'${frozenScriptName}' due to unhandled exception!\n`,
  );
  process.exitCode = UNHANDLED_EXCEPTION_STATUS;
}

