#!/usr/bin/env node
/**
 * Differential harness: run the reference executable and the Node port with
 * identical argv, then compare stdout, exit status and (normalised) stderr.
 *
 * Cases arrive on stdin as JSON lines, each `{"args": [...], "name": "..."}`.
 * Args may use the escape `{"raw": "<bash $'...' body>"}` for byte sequences
 * that cannot survive a JS string.
 *
 * Exit status 0 = every case matched.
 */

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REFERENCE = '/workspace/dataset/test13_executable';
const PORT = ['node', '/output/test13.mjs'];

const normalise = (text) =>
  text
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]')
    .replace(/test13_executable/g, '<prog>')
    .replace(/test13\.mjs/g, '<prog>');

/**
 * Build a bash command that execs `argv0` with the given args, supporting raw
 * byte escapes.
 */
function bashInvocation(command, args) {
  const quoted = args.map((a) =>
    typeof a === 'object' && a !== null && 'raw' in a
      ? `$'${a.raw}'`
      : `'${String(a).replace(/'/g, `'\\''`)}'`,
  );
  return `exec ${command.map((c) => `'${c.replace(/'/g, `'\\''`)}'`).join(' ')} ${quoted.join(' ')}`;
}

function run(command, args, env) {
  const result = spawnSync('/bin/bash', ['-c', bashInvocation(command, args)], {
    encoding: 'latin1',
    env: { ...process.env, ...env },
    maxBuffer: 64 * 1024 * 1024,
  });
  return {
    status: result.status,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}

const cases = readFileSync(process.argv[2] ?? 0, 'utf8')
  .split('\n')
  .filter((line) => line.trim() !== '')
  .map((line) => JSON.parse(line));

let failures = 0;
let checked = 0;

for (const testCase of cases) {
  const env = testCase.env ?? {};
  const expected = run([REFERENCE], testCase.args, env);
  const actual = run(PORT, testCase.args, env);
  checked += 1;

  const problems = [];
  if (expected.stdout !== actual.stdout) problems.push('stdout');
  if (expected.status !== actual.status) problems.push('status');
  if (normalise(expected.stderr) !== normalise(actual.stderr)) problems.push('stderr');

  if (problems.length > 0) {
    failures += 1;
    if (failures <= 25) {
      console.log(`FAIL [${problems.join(',')}] ${testCase.name ?? ''}`);
      console.log(`  args     : ${JSON.stringify(testCase.args)}`);
      if (Object.keys(env).length > 0) console.log(`  env      : ${JSON.stringify(env)}`);
      if (problems.includes('status')) {
        console.log(`  status   : want ${expected.status} got ${actual.status}`);
      }
      if (problems.includes('stdout')) {
        console.log(`  want out : ${JSON.stringify(expected.stdout)}`);
        console.log(`  got  out : ${JSON.stringify(actual.stdout)}`);
      }
      if (problems.includes('stderr')) {
        console.log(`  want err : ${JSON.stringify(normalise(expected.stderr))}`);
        console.log(`  got  err : ${JSON.stringify(normalise(actual.stderr))}`);
      }
    }
  }
}

console.log(`\nchecked ${checked} cases, ${failures} failures`);
process.exit(failures === 0 ? 0 : 1);

