/**
 * CPython's `linecache`, as far as traceback rendering needs it.
 *
 * The frozen reference program records its frames with the *relative* filename
 * `test13.py`, so whether a traceback shows source lines depends on whether
 * such a file can be read from the current working directory and decoded as
 * UTF-8 — a file with undecodable bytes yields no source lines at all, exactly
 * as `tokenize.open` raising `UnicodeDecodeError` makes `updatecache` give up.
 */

import { readFileSync } from 'node:fs';

/** @type {Map<string, string[] | null>} */
const cache = new Map();

/**
 * Split like `str.splitlines(keepends=True)` for the line endings that matter
 * in source files.
 *
 * @param {string} text
 * @returns {string[]}
 */
function splitKeepingEnds(text) {
  const lines = text.split(/(?<=\r\n|\n|\r)/);
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  return lines;
}

/**
 * Read and cache a file's lines, or remember that it is unreadable.
 *
 * @param {string} filename
 * @returns {string[] | null}
 */
function getLines(filename) {
  if (!cache.has(filename)) {
    try {
      const bytes = readFileSync(filename);
      const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
      cache.set(filename, splitKeepingEnds(text));
    } catch {
      cache.set(filename, null);
    }
  }
  return cache.get(filename) ?? null;
}

/**
 * `linecache.getline`: the requested line including its terminator, or the
 * empty string when unavailable.
 *
 * @param {string} filename
 * @param {number} lineno 1-based
 * @returns {string}
 */
export function getLine(filename, lineno) {
  const lines = getLines(filename);
  if (lines === null || lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

