/**
 * Rendering an unhandled exception the way CPython does, plus the notice the
 * PyInstaller bootloader prints for the frozen script.
 *
 * The layout below was pinned against the reference binary, including the
 * cases where a doctored source file makes the offsets disagree with the code
 * object:
 *
 *   - the echoed line keeps trailing whitespace but loses its indent;
 *   - the caret indent is `startOffset - (len(rawLine) - len(echoedLine))`;
 *   - offsets recorded by the compiler are *byte* offsets, converted to
 *     character offsets against the line actually on disk, which also clamps
 *     them to the end of that line;
 *   - the caret row is omitted only when the expression spans the whole line.
 *
 * Lengths are counted in code points, matching Python's `len()` on `str`.
 */

import { getLine } from './linecache.mjs';
import { writeStderr } from './sys.mjs';

/** Exit status the interpreter uses for an unhandled exception. */
const UNHANDLED_EXCEPTION_STATUS = 1;

/** Indent CPython uses for echoed source and caret rows. */
const SOURCE_INDENT = '    ';

/**
 * `len(text)` for a Python `str`: a count of code points.
 *
 * @param {string} text
 * @returns {number}
 */
function codePointLength(text) {
  return Array.from(text).length;
}

/**
 * `traceback._byte_offset_to_character_offset`: where a UTF-8 byte offset lands
 * once the line is measured in characters. Offsets past the end of the line
 * clamp to its length.
 *
 * @param {string} line
 * @param {number} byteOffset
 * @returns {number}
 */
function byteOffsetToCharacterOffset(line, byteOffset) {
  const encoded = Buffer.from(line, 'utf8');
  const prefix = new TextDecoder('utf-8').decode(encoded.subarray(0, byteOffset));
  return codePointLength(prefix);
}

/**
 * The source and caret rows for one frame, or '' when the source is not
 * available from the working directory.
 *
 * @param {{file: string, line: number, colOffset?: number, endColOffset?: number}} frame
 * @returns {string}
 */
function formatFrameSource(frame) {
  const rawLine = getLine(frame.file, frame.line);
  if (rawLine === '') return '';

  // The echoed line loses its indent and its newline, but keeps trailing space.
  const withoutNewline = rawLine.replace(/\r?\n$|\r$/, '');
  const echoed = withoutNewline.replace(/^[\s﻿ ]+/, '');
  let out = `${SOURCE_INDENT}${echoed}\n`;

  if (frame.colOffset === undefined || frame.endColOffset === undefined) return out;

  const strippedCharacters = codePointLength(rawLine) - codePointLength(echoed);
  const startOffset = byteOffsetToCharacterOffset(rawLine, frame.colOffset) + 1;
  const endOffset = byteOffsetToCharacterOffset(rawLine, frame.endColOffset) + 1;
  const caretCount = endOffset - startOffset;

  // Carets are shown only when the expression does not span the whole line.
  if (caretCount >= codePointLength(echoed)) return out;

  const indent = Math.max(0, startOffset - strippedCharacters);
  out += `${SOURCE_INDENT}${' '.repeat(indent)}${'^'.repeat(Math.max(0, caretCount))}\n`;
  return out;
}

/**
 * Render a traceback for an exception carrying `pythonType`, `message` and
 * `pythonFrames`.
 *
 * @param {{pythonType: string, message: string, pythonFrames: object[]}} error
 * @returns {string}
 */
