#!/usr/bin/env node
/**
 * Differential harness: run the reference executable and the Node port with
 * identical argv, then compare stdout, exit status and (normalised) stderr.
 *
 * Usage: node diff.mjs <cases.jsonl> [--cwd <dir>] [--jobs N]
 *
 * Cases are JSON lines: {"name": "...", "args": [...], "env": {...}}.
 * An arg may be {"raw": "<bash $'...' body>"} for byte sequences a JS string
 * cannot carry.
 *
 * Exit status 0 = every case matched.
 */

import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REFERENCE = ['/workspace/dataset/test13_executable'];
const PORT = ['node', '/output/test13.mjs'];

const argv = process.argv.slice(2);
const casesPath = argv[0];
const option = (name, fallback) => {
  const at = argv.indexOf(name);
  return at === -1 ? fallback : argv[at + 1];
};
const workingDirectory = option('--cwd', process.cwd());
const jobs = Number(option('--jobs', '16'));

const normalise = (text) =>
  text
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]')
    .replace(/test13_executable/g, '<prog>')
    .replace(/test13\.mjs/g, '<prog>');

const shellQuote = (text) => `'${text.replace(/'/g, `'\\''`)}'`;

/** Build a bash command that execs a program with possibly-raw byte args. */
function invocation(command, args) {
  const quoted = args.map((argument) =>
    typeof argument === 'object' && argument !== null && 'raw' in argument
      ? `$'${argument.raw}'`
      : shellQuote(String(argument)),
  );
  return `exec ${command.map(shellQuote).join(' ')} ${quoted.join(' ')}`;
}

/** Run one program, collecting output as latin1 so bytes survive intact. */
function run(command, args, env) {
  return new Promise((resolve) => {
    const child = spawn('/bin/bash', ['-c', invocation(command, args)], {
      cwd: workingDirectory,
      env: { ...process.env, ...env },
    });
    const out = [];
    const err = [];
    child.stdout.on('data', (chunk) => out.push(chunk));
    child.stderr.on('data', (chunk) => err.push(chunk));
    child.on('close', (status) =>
      resolve({
        status,
        stdout: Buffer.concat(out).toString('latin1'),
        stderr: Buffer.concat(err).toString('latin1'),
      }),
    );
  });
}

/** Compare one case; resolves to a failure report or null. */
async function check(testCase) {
  const env = testCase.env ?? {};
  const [expected, actual] = await Promise.all([
    run(REFERENCE, testCase.args, env),
    run(PORT, testCase.args, env),
  ]);

  const problems = [];
  if (expected.stdout !== actual.stdout) problems.push('stdout');
  if (expected.status !== actual.status) problems.push('status');
  if (normalise(expected.stderr) !== normalise(actual.stderr)) problems.push('stderr');
  if (problems.length === 0) return null;

  const report = [
    `FAIL [${problems.join(',')}] ${testCase.name ?? ''}`,
    `  args     : ${JSON.stringify(testCase.args)}`,
  ];
  if (Object.keys(env).length > 0) report.push(`  env      : ${JSON.stringify(env)}`);
  if (problems.includes('status')) {
    report.push(`  status   : want ${expected.status} got ${actual.status}`);
  }
  if (problems.includes('stdout')) {
    report.push(`  want out : ${JSON.stringify(expected.stdout)}`);
    report.push(`  got  out : ${JSON.stringify(actual.stdout)}`);
  }
  if (problems.includes('stderr')) {
    report.push(`  want err : ${JSON.stringify(normalise(expected.stderr))}`);
    report.push(`  got  err : ${JSON.stringify(normalise(actual.stderr))}`);
  }
  return report.join('\n');
}

const cases = readFileSync(casesPath, 'utf8')
  .split('\n')
  .filter((line) => line.trim() !== '')
  .map((line) => JSON.parse(line));

let failures = 0;
let next = 0;

async function worker() {
  for (;;) {
    const index = next;
    next += 1;
    if (index >= cases.length) return;
    const failure = await check(cases[index]);
    if (failure !== null) {
      failures += 1;
      if (failures <= 30) console.log(failure);
    }
  }
}

await Promise.all(Array.from({ length: Math.min(jobs, cases.length) }, worker));

console.log(
  `\ncwd=${workingDirectory} checked ${cases.length} cases, ${failures} failures`,
);
process.exit(failures === 0 ? 0 : 1);

