#!/usr/bin/env node
/**
 * Node port of /workspace/dataset/test13.py
 *
 *   import argparse
 *   import pyaes
 *
 *   def main():
 *       parser = argparse.ArgumentParser()
 *       parser.add_argument('--key', type=str, required=True)   # 16 bytes key
 *       parser.add_argument('--data', type=str, required=True)  # 16 bytes data
 *       args = parser.parse_args()
 *
 *       # Test round-trip encryption/decryption with ECB
 *       aes = pyaes.AESModeOfOperationECB(args.key.encode())
 *       ciphertext = aes.encrypt(args.data.encode())
 *       plaintext = aes.decrypt(ciphertext)
 *       print(ciphertext)
 *       print(plaintext)
 *
 * Usage: node test13.mjs --key KEY --data DATA
 */

import * as pyaes from './lib/aes/index.mjs';
import { ArgumentParser } from './lib/python/argparse.mjs';
import { programName, pythonArgv } from './lib/python/argv.mjs';
import { encodeUtf8Strict } from './lib/python/codecs.mjs';
import { PythonError } from './lib/python/exceptions.mjs';
import { addOuterFrame, frame } from './lib/python/frames.mjs';
import { reprBytes } from './lib/python/reprBytes.mjs';
import { print } from './lib/python/sys.mjs';
import { reportUnhandledException } from './lib/python/traceback.mjs';

/** Identity of the original script, as it appears in tracebacks. */
const SCRIPT = 'test13.py';
const FROZEN_SCRIPT = 'test13';

/**
 * Source lines of the original script, indent included.
 *
 * Only their geometry is used: the compiler records the byte offsets of each
 * failing sub-expression within its line, and the traceback renderer combines
 * those with whatever `test13.py` it can read from the working directory.
 */
const STATEMENTS = {
  moduleCall: { line: 18, text: '    main()' },
  init: {
    line: 11,
    text:
      '    aes = pyaes.AESModeOfOperationECB(args.key.encode())  # Initialize AES ECB cipher',
  },
  encrypt: {
    line: 12,
    text: '    ciphertext = aes.encrypt(args.data.encode())  # Encrypt plaintext',
  },
  decrypt: {
    line: 13,
    text: '    plaintext = aes.decrypt(ciphertext)  # Decrypt ciphertext back',
  },
};

/**
 * Build the frame CPython would report for one sub-expression of a statement.
 *
 * @param {{line: number, text: string}} statement
 * @param {string} name enclosing function name
 * @param {string} expression the exact sub-expression being evaluated
 * @returns {object}
 */
function frameFor(statement, name, expression) {
  const colOffset = statement.text.indexOf(expression);
  return frame(SCRIPT, statement.line, name, {
    colOffset,
    endColOffset: colOffset + expression.length,
  });
}

/**
 * Evaluate one sub-expression of `main`, tagging any Python-level exception
 * with the frame CPython would report for it.
 *
 * @template T
 * @param {{line: number, text: string}} statement
 * @param {string} expression the exact sub-expression being evaluated
 * @param {() => T} evaluate
 * @returns {T}
 */
function evaluated(statement, expression, evaluate) {
  try {
    return evaluate();
  } catch (error) {
    if (!(error instanceof PythonError)) throw error;
    throw addOuterFrame(error, frameFor(statement, 'main', expression));
  }
}

/** Port of `main()`. */
function main() {
  const parser = new ArgumentParser({ prog: programName() });
  parser.addArgument(['--key'], { required: true }); // 16 bytes key
  parser.addArgument(['--data'], { required: true }); // 16 bytes data
  const args = parser.parseArgs(pythonArgv());

  // Test round-trip encryption/decryption with ECB
  const key = evaluated(STATEMENTS.init, 'args.key.encode()', () =>
    encodeUtf8Strict(args.key),
  );
  const aes = evaluated(
    STATEMENTS.init,
    'pyaes.AESModeOfOperationECB(args.key.encode())',
    () => new pyaes.AESModeOfOperationECB(key), // Initialize AES ECB cipher
  );

  const data = evaluated(STATEMENTS.encrypt, 'args.data.encode()', () =>
    encodeUtf8Strict(args.data),
  );
  const ciphertext = evaluated(
    STATEMENTS.encrypt,
    'aes.encrypt(args.data.encode())',
    () => aes.encrypt(data), // Encrypt plaintext
  );

  const plaintext = evaluated(STATEMENTS.decrypt, 'aes.decrypt(ciphertext)', () =>
    aes.decrypt(ciphertext), // Decrypt ciphertext back
  );

  print(reprBytes(ciphertext));
  print(reprBytes(plaintext));
}

// if __name__ == '__main__': main()
