  if (SBOX[i] !== want) { bad += 1; console.log(`FAIL SBOX[${i}]=${SBOX[i].toString(16)} want ${want.toString(16)}`); }
}
if (!SBOX.every((v, i) => INV_SBOX[v] === i)) { bad += 1; console.log('FAIL inverse S-box'); }
if (new Set(SBOX).size !== 256) { bad += 1; console.log('FAIL S-box not bijective'); }
const rconWant = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36, 0x6c, 0xd8, 0xab, 0x4d];
rconWant.forEach((w, i) => { if (RCON[i + 1] !== w) { bad += 1; console.log(`FAIL RCON[${i + 1}]`); } });

// FIPS-197 Appendix A key expansion first/last words.
