if (w128.length !== 44 || w128[43] >>> 0 !== 0xb6630ca6) { bad += 1; console.log(`FAIL AES-128 schedule tail ${(w128[43] >>> 0).toString(16)}`); }
const w192 = expandKey(hex('8e73b0f7da0e6452c810f32b809079e562f8ead2522c6b7b'));
if (w192.length !== 52 || w192[51] >>> 0 !== 0x01002202) { bad += 1; console.log(`FAIL AES-192 schedule tail ${(w192[51] >>> 0).toString(16)}`); }
const w256 = expandKey(hex('603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4'));
if (w256.length !== 60 || w256[59] >>> 0 !== 0x706c631e) { bad += 1; console.log(`FAIL AES-256 schedule tail ${(w256[59] >>> 0).toString(16)}`); }

// Round-trip every key size over random blocks.
let seed = 12345;
const rand = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) % 256;
for (const size of [16, 24, 32]) {
  for (let t = 0; t < 3000; t += 1) {
