#!/usr/bin/env node
/** Large mixed random campaign: node mega.mjs <count> <seed> */
const [count = '5000', seed = '1'] = process.argv.slice(2);
let state = Number(seed) | 0 || 1;
const rnd = () => {
  state ^= state << 13; state ^= state >>> 17; state ^= state << 5;
  return ((state >>> 0) % 2147483647) / 2147483647;
};
const int = (n) => Math.floor(rnd() * n);
const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i));
const UNI = ['é', '€', '𝄞', 'ü', '日', 'ø', 'ß', '¢', '☃', '🎉', ' ', '�', 'a', 'Z', '0'];
const RAWBAD = ['\\xff', '\\x80', '\\xc0', '\\xe0\\x80', '\\xf5', '\\xed\\xa0\\x80', '\\xc3', '\\xf0\\x9f\\x8e'];
const JUNK = ['--foo', '-x', '--', '-', '--key', '--data', '-h', '--k', '--d', '=', '--=1', '-1', '-1.5', '-a b', 'plain', '', '--data=', '--key='];
const pick = (a) => a[int(a.length)];
const ascii = (n) => Array.from({ length: n }, () => pick(PRINTABLE)).join('');
const uni = (n) => Array.from({ length: n }, () => pick(UNI)).join('');

for (let i = 0; i < Number(count); i += 1) {
  const mode = int(10);
  let args;
  let env;
  if (mode < 3) {
    args = ['--key', ascii(pick([16, 16, 16, 24, 32])), '--data', ascii(16)];
  } else if (mode === 3) {
    args = ['--key', ascii(pick([0, 1, 8, 15, 16, 17, 23, 24, 25, 31, 32, 33, 48])), '--data', ascii(int(34))];
  } else if (mode === 4) {
    args = ['--key', pick([ascii(16), uni(int(12))]), '--data', uni(int(12))];
  } else if (mode === 5) {
    const bad = Array.from({ length: 1 + int(3) }, () => pick(RAWBAD)).join('');
    const filler = 'abcdefghijklmnopqrst'.slice(0, int(18));
    args = [
      '--key', int(2) ? ascii(16) : { raw: `yPcJ.h9oOX7e5!c${pick(RAWBAD)}` },
      '--data', { raw: int(2) ? `${filler}${bad}` : `${bad}${filler}` },
    ];
  } else if (mode === 6) {
    const tokens = [];
    const n = 1 + int(6);
    for (let t = 0; t < n; t += 1) {
      const r = int(4);
      if (r === 0) tokens.push(pick(JUNK));
      else if (r === 1) tokens.push(pick(['--key', '--k', '--ke', `--key=${ascii(16)}`]));
      else if (r === 2) tokens.push(pick(['--data', '--d', '--dat', `--data=${ascii(16)}`]));
      else tokens.push(ascii(1 + int(18)));
    }
    args = tokens;
  } else if (mode === 7) {
    args = pick([['--help'], ['-h'], [], ['--key', ascii(16)], ['--data', ascii(16)]]);
    env = { COLUMNS: String(8 + int(120)) };
  } else if (mode === 8) {
    // Bytes chosen to stress repr: quotes, backslashes, control chars.
    const pool = ["'", '"', '\\', ' ', '\t', 'a', '\x01', '\x7f'];
    args = ['--key', ascii(16), '--data', Array.from({ length: 16 }, () => pick(pool)).join('')];
  } else {
    args = ['--key', ascii(pick([16, 24, 32])), '--data', ascii(16)];
    env = { COLUMNS: String(8 + int(120)) };
  }
  console.log(JSON.stringify(env ? { name: `mega#${i}/m${mode}`, args, env } : { name: `mega#${i}/m${mode}`, args }));
}
