/**
 * The width argparse formats help against.
 *
 * `shutil.get_terminal_size()` prefers `$COLUMNS` — parsed with `int()`, so a
 * value that is not a plain integer is ignored rather than truncated — then the
 * terminal, then falls back to 80 columns, which is what happens whenever
 * stdout is a pipe.
 *
 * @returns {number} total columns
 */
export function terminalColumns() {
  const columns = process.env.COLUMNS ?? '';
  if (/^\s*[+-]?\d+\s*$/.test(columns)) {
    const parsed = Number.parseInt(columns, 10);
    if (parsed > 0) return parsed;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

