/**
 * argparse's `HelpFormatter`, reduced to the cases this parser can produce
 * (optionals only, at most one metavar each) but keeping the real layout
 * arithmetic: help-column placement, usage wrapping and help-text wrapping all
 * respond to the terminal width exactly as CPython 3.12 does.
 */

import { collapseWhitespace, wrapText } from './textwrap.mjs';

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;

/**
 * `_format_usage`'s part splitter: bracketed/parenthesised groups stay whole,
 * everything else splits on whitespace.
 */
const PART_PATTERN = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

export class HelpFormatter {
  /**
   * @param {string} prog program name
   * @param {number} columns terminal width
   */
  constructor(prog, columns) {
    this.prog = prog;
    this.width = columns - 2;
    this.currentIndent = 0;
    this.maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
  }

  /**
   * How an action appears in the usage line: `[-h]`, `--key KEY`.
   *
   * @param {object} action
   * @returns {string}
   */
  usagePart(action) {
    const optionString = action.optionStrings[0];
    const part = action.nargs === 0 ? optionString : `${optionString} ${action.metavar}`;
    return action.required ? part : `[${part}]`;
  }

  /**
   * How an action appears in the options list: `-h, --help`, `--key KEY`.
   *
   * @param {object} action
   * @returns {string}
   */
  invocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
  }

  /**
   * The width of the widest invocation plus its indent, i.e. argparse's
   * `_action_max_length`.
   *
   * @param {object[]} actions
   * @returns {number}
   */
  actionMaxLength(actions) {
    let longest = 0;
    for (const action of actions) {
      longest = Math.max(longest, this.invocation(action).length + INDENT_INCREMENT);
    }
    return longest;
  }

  /**
   * Greedy line packing shared by both usage-wrapping branches, mirroring the
   * nested `get_lines` helper in `_format_usage`.
   *
   * @param {string[]} parts
   * @param {string} indent
   * @param {number} textWidth
   * @param {string | null} prefix
   * @returns {string[]}
   */
  static packLines(parts, indent, textWidth, prefix = null) {
    const lines = [];
    let line = [];
    let lineLength = (prefix === null ? indent.length : prefix.length) - 1;

    for (const part of parts) {
      if (lineLength + 1 + part.length > textWidth && line.length > 0) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLength = indent.length - 1;
      }
      line.push(part);
      lineLength += 1 + part.length;
    }
    if (line.length > 0) lines.push(indent + line.join(' '));
    if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
    return lines;
  }

  /**
   * The `usage: ...` block, wrapped if it does not fit the terminal.
   *
   * @param {object[]} actions
   * @returns {string} ends with a single newline
   */
  formatUsage(actions) {
    const prefix = 'usage: ';
    const actionUsage = actions.map((action) => this.usagePart(action)).join(' ');
    let usage = [this.prog, actionUsage].filter((piece) => piece !== '').join(' ');
    const textWidth = this.width - this.currentIndent;

    if (prefix.length + usage.length > textWidth) {
      const optionalParts = actionUsage.match(PART_PATTERN) ?? [];
      let lines;
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
        lines =
          optionalParts.length > 0
            ? HelpFormatter.packLines([this.prog, ...optionalParts], indent, textWidth, prefix)
            : [this.prog];
      } else {
        const indent = ' '.repeat(prefix.length);
        lines = HelpFormatter.packLines(optionalParts, indent, textWidth);
        lines = [this.prog, ...lines];
      }
      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n`;
  }

  /**
   * One entry of the options list, including any wrapped help text.
   *
   * @param {object} action
   * @param {number} helpPosition
   * @returns {string}
   */
  formatAction(action, helpPosition) {
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
    const header = this.invocation(action);
    const helpText = action.help ? collapseWhitespace(action.help) : '';

    if (helpText === '') {
      return `${' '.repeat(INDENT_INCREMENT)}${header}\n`;
    }

    const helpLines = wrapText(helpText, helpWidth);
    let out = '';
    let firstIndent;
    if (header.length <= actionWidth) {
      out += `${' '.repeat(INDENT_INCREMENT)}${header.padEnd(actionWidth)}  `;
      firstIndent = 0;
    } else {
      out += `${' '.repeat(INDENT_INCREMENT)}${header}\n`;
      firstIndent = helpPosition;
    }
    out += `${' '.repeat(firstIndent)}${helpLines[0]}\n`;
    for (const line of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${line}\n`;
    }
    return out;
  }

  /**
   * The complete `--help` output.
   *
   * @param {object[]} actions
   * @returns {string}
   */
  formatHelp(actions) {
    const helpPosition = Math.min(this.actionMaxLength(actions) + 2, this.maxHelpPosition);
    const entries = actions.map((action) => this.formatAction(action, helpPosition)).join('');
    const body = entries === '' ? '' : `\noptions:\n${entries}\n`;
    const help = `${this.formatUsage(actions)}\n${body}`;
    return `${help.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

