/**
 * The slice of `sys` this program touches.
 *
 * Stream buffering follows CPython: `sys.stdout` is line buffered on a
 * terminal but *block* buffered on a pipe or file, so a piped run emits its
 * whole output in a single write at interpreter shutdown. That difference is
 * observable — `prog | head -1` succeeds quietly against the reference because
 * nothing is written until the buffer is flushed — so it is reproduced here,
 * along with the diagnostics CPython prints when that final flush fails.
 *
 * Writes go out as raw bytes via `writeSync` so they are safe to perform from
 * an exit handler and nothing re-encodes the text on its way to the fd.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

/** CPython's default block-buffer size for a non-tty stdout. */
const BLOCK_BUFFER_SIZE = 8192;

/** How CPython names the errno values a flush can fail with. */
const FLUSH_ERRORS = {
  EPIPE: { type: 'BrokenPipeError', errno: 32, text: 'Broken pipe' },
  ENOSPC: { type: 'OSError', errno: 28, text: 'No space left on device' },
};

/** @type {Buffer[]} */
let buffered = [];
let bufferedLength = 0;
let flushReported = false;

/**
 * Write a whole buffer to a file descriptor, tolerating partial writes and a
 * non-blocking pipe.
 *
 * @param {number} fd
 * @param {Buffer} buffer
 */
function writeAll(fd, buffer) {
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      throw error;
    }
  }
}

/**
 * Reproduce the shutdown diagnostics CPython emits when it cannot flush
 * stdout: the exception from the frozen entry point, then the "ignored"
 * exception from closing the stream. The exit status stays unchanged, which is
 * what the reference does.
 *
 * @param {NodeJS.ErrnoException} error
 */
function reportFlushFailure(error) {
  if (flushReported) return;
  flushReported = true;
  const kind = FLUSH_ERRORS[error.code ?? ''] ?? {
    type: 'OSError',
    errno: error.errno ?? 0,
    text: error.message,
  };
  const description = `${kind.type}: [Errno ${kind.errno}] ${kind.text}\n`;
  try {
    writeAll(
      STDERR_FD,
      Buffer.from(
        'Traceback (most recent call last):\n' +
          '  File "<string>", line 1, in <module>\n' +
          description +
          "Exception ignored in: <_io.TextIOWrapper name='<stdout>' mode='w' " +
          "encoding='utf-8'>\n" +
          description,
        'utf8',
      ),
    );
  } catch {
    // Nothing left to report to.
  }
}

/**
 * Flush everything buffered for stdout.
 */
export function flushStdout() {
  if (buffered.length === 0) return;
  const payload = Buffer.concat(buffered);
  buffered = [];
  bufferedLength = 0;
  try {
    writeAll(STDOUT_FD, payload);
  } catch (error) {
    reportFlushFailure(error);
  }
}

// CPython flushes stdout as the interpreter shuts down.
process.on('exit', flushStdout);

/**
 * `sys.stdout.write`
 *
 * @param {string} text
 */
export function writeStdout(text) {
  const payload = Buffer.from(text, 'utf8');
  if (process.stdout.isTTY) {
    // Line buffered: a terminal sees output as it is produced.
    try {
      writeAll(STDOUT_FD, payload);
    } catch (error) {
      reportFlushFailure(error);
    }
    return;
  }
  buffered.push(payload);
  bufferedLength += payload.length;
  if (bufferedLength >= BLOCK_BUFFER_SIZE) flushStdout();
}

/**
 * `sys.stderr.write` — unbuffered, like CPython's stderr.
 *
 * @param {string} text
 */
export function writeStderr(text) {
  try {
    writeAll(STDERR_FD, Buffer.from(text, 'utf8'));
  } catch {
    // A closed stderr is not worth reporting anywhere.
  }
}

/**
 * `print(...)` for a single already-stringified argument.
 *
 * @param {string} text
 */
export function print(text) {
  writeStdout(`${text}\n`);
}

/**
 * `sys.exit(status)`
 *
 * @param {number} status
 * @returns {never}
 */
export function exit(status) {
  process.exit(status);
}

/**
 * The width argparse formats help against.
 *
 * `shutil.get_terminal_size()` prefers `$COLUMNS` — parsed with `int()`, so a
 * value that is not a plain integer is ignored rather than truncated — then the
 * terminal, then falls back to 80 columns, which is what happens whenever
 * stdout is a pipe.
 *
 * @returns {number} total columns
 */
export function terminalColumns() {
  const columns = process.env.COLUMNS ?? '';
  if (/^\s*[+-]?\d+\s*$/.test(columns)) {
    const parsed = Number.parseInt(columns, 10);
    if (parsed > 0) return parsed;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

